bool isIndefiniteTiming( const uno::Any& rAny )
        {
            if( !rAny.hasValue() )
                return true;

            animations::Timing eTiming;

            return (rAny >>= eTiming) && eTiming == animations::Timing_INDEFINITE;
        }
